  });
  return (
    <div ref={boxRef} style={{ height: "100%" }}>
      <OrderBookHeatmap
        ref={heatmapRef}
        interval={150}
        window={30_000}
        profile={false}
        bubbleSize={12}
        fontSize={10}
        pricePrecision={1}
        sizePrecision={3}
        locale={i18n.language}
        height="100%"
        ariaLabel={ariaLabel}
      />
    </div>
  );
}

